"""Sales-focused static page. Copy and examples live in content.json."""
from html import escape as e
from character import render_tea
from guided import render_conversation, render_journey, render_reader_explorer

def render_sales(c,buy,icon,foot,document):
 s=c['sales'];u=c['ui'];price=f"${c['price']:g}"
 hero_buy=buy('hero').replace('class="button"','class="text-link hero-purchase"')
 head=lambda eyebrow,title,body='':f'<p class="eyebrow">{e(eyebrow)}</p><h2>{e(title)}</h2>'+ (f'<p class="intro">{e(body)}</p>' if body else '')
 nav=f'''<header class="topbar" id="topbar"><div class="wrap nav-inner"><a class="wordmark" href="#hero">{e(c['brand'])}<span>.</span></a><nav aria-label="Main navigation"><a href="#the-approach">Alicia’s approach</a><a href="#chapters">The chapters</a><span class="nav-price">{price}</span>{buy('navigation',u['getPlaybook'])}</nav></div></header>'''
 hero=f'''<section class="sales-hero" id="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="eyebrow">{e(s['productLabel'])}</p><h1>{e(s['heroHeadline'])}<br><em>{e(s['heroEmphasis'])}</em></h1><p class="hero-lede">{e(c['hero']['lede'])}</p><p class="hero-support">{e(c['hero']['support'])}</p><div class="hero-actions"><a class="button" href="#the-approach">{e(s['heroSecondary'])}{icon('arrow')}</a>{hero_buy}</div><p class="hero-terms">{e(s['heroInvitation'])}</p><ul class="benefits">{''.join(f'<li>{icon("tick")}{e(x)}</li>' for x in s['benefits'])}</ul><p class="hero-foot">{e(s['heroFoot'])}</p></div><div class="hero-visual"><div class="visual-halo" aria-hidden="true"></div><div class="book-object" role="img" aria-label="{e(s['coverAlt'])}"><div class="book-cover"><span>{e(c['slogan'])}</span><strong>The Quiet<br>Wealth<br><em>Playbook.</em></strong><div class="cover-lines" aria-hidden="true"><i></i><i></i><i></i></div><p>{e(s['coverBottom'])}</p><small>{e(c['brand'])}</small></div></div><img class="hero-alicia" data-life src="assets/alicia-shh-v3.webp" width="800" height="1200" fetchpriority="low" decoding="async" alt="{e(c['hero']['portraitAlt'])}"><p class="hero-handnote">{e(s['heroHandnote'])}</p><p class="visual-caption">{e(s['coverNote'])}</p></div></div></section>'''
 trust=f'''<section class="channel-strip"><div class="wrap"><span>{icon('tick')}{e(s['trustLine'])}</span><p>{e(s['trustNote'])}</p></div></section>'''
 core=''.join(f'<article class="core-card"><p class="eyebrow">{e(x["label"])}</p><h3>{e(x["title"])}</h3><p>{e(x["body"])}</p><div><strong>{e(x["metric"])}</strong><span>{e(x["detail"])}</span></div></article>' for x in s['core'])
 inventory=''.join(f'<article class="resource-card"><span>{i+1:02d}</span><div><h3>{e(x["name"])}</h3><p>{e(x["body"])}</p></div></article>' for i,x in enumerate(c['pack']['items']))
 pack=f'''<section class="section-space wrap" id="the-pack"><div class="section-heading">{head(c['pack']['eyebrow'],s['packHeading'],s['packIntro'])}</div><div class="core-grid">{core}</div><details class="resource-inventory"><summary>{e(s['inventoryTitle'])}{icon('plus')}</summary><div class="resource-grid">{inventory}</div></details><p class="format-note">{icon('folder')}{e(s['formats'])}</p></section>'''
 compare=''
 pack=pack.replace('</section>','<details class="pack-context"><summary>'+e(s['differenceTitle'])+icon('plus')+'</summary><p>'+e(s['differenceIntro'])+'</p><ul>'+''.join('<li>'+e(x['pack'])+'</li>' for x in s['comparison'])+'</ul></details></section>')

 rows=''.join(f'''<div class="cost-row" data-cost-row><div class="cost-name"><label for="cost-name-{i}">{e(s['expenseLabel'])} {i+1}</label><input id="cost-name-{i}" data-cost-name value="{e(x['name'])}" maxlength="60"></div><div><label for="cost-amount-{i}">{e(s['costLabel'])}</label><div class="dollar-input"><span aria-hidden="true">$</span><input id="cost-amount-{i}" data-cost-amount type="number" min="0" max="10000" step="0.01" inputmode="decimal" value="{x['amount']}"></div></div><div><label for="cost-frequency-{i}">{e(s['frequencyLabel'])}</label><select id="cost-frequency-{i}" data-cost-frequency>{''.join(f'<option value="{k}"'+(' selected' if k==x['frequency'] else '')+f'>{e(v)}</option>' for k,v in s['frequencyLabels'].items())}</select></div><label class="review-choice"><input type="checkbox" data-cost-review {'checked' if x['review'] else ''}><span>{e(s['reviewLabel'])}</span></label></div>''' for i,x in enumerate(s['defaultRows']))
 demo=f'''<section class="starter-section section-space" id="try-it"><div class="wrap"><div class="starter-heading"><div>{head(s['starterEyebrow'],s['starterHeading'],s['starterIntro'])}</div><img data-life src="assets/alicia-workbook-v5.webp" width="1000" height="667" loading="lazy" alt="{e(s['workbookAlt'])}"></div><div class="starter-tool" data-cost-tool><p class="tool-example">{e(s['defaultDemoNote'])}</p>{rows}<div class="tool-results" aria-live="polite" aria-atomic="true"><div><span>{e(s['annualTotal'])}</span><output data-cost-total>$912</output></div><div class="review-result"><span>{e(s['reviewTotal'])}</span><output data-review-total>$300</output><small>{e(s['reviewNote'])}</small></div></div><div class="tool-footer"><div><button class="button" type="button" data-download-costs>{e(s['downloadLabel'])}{icon('arrow')}</button><a class="text-link" href="starter-worksheet.html">{e(s['printLabel'])}</a></div><p>{e(s['demoPrivacy'])}</p></div><p class="tool-status" role="status" data-tool-status></p></div><p class="example-disclosure">{e(s['demoNotice'])}</p><noscript><p class="example-disclosure">{e(s['noJsDemo'])}</p></noscript></div></section>'''
 examples=''.join(f'''<article class="example-card"><div class="example-top"><span>{e(x['number'])} / {e(x['tag'])}</span>{icon(['grid','message','check'][i])}</div><h3>{e(x['title'])}</h3><p>{e(x['intro'])}</p><details><summary>{e(s['exampleDetails'])}{icon('plus')}</summary>{f'<blockquote>{e(x["quote"])}</blockquote>' if x.get('quote') else ''}<ol>{''.join(f'<li>{e(t)}</li>' for t in x['steps'])}</ol><p class="example-note">{e(x['footer'])}</p></details><a class="text-link" href="{e(x['slug'])}.html">{e(s['printLabel'])}{icon('arrow')}</a></article>''' for i,x in enumerate(s['examples']))
 samples=f'''<section class="section-space wrap" id="look-inside"><div class="section-heading">{head(s['samplesEyebrow'],s['samplesHeading'],s['samplesIntro'])}</div><div class="example-grid" id="sample-pages">{examples}</div><p class="example-disclosure">{e(s['sampleDisclosure'])}</p></section>'''
 if c.get('productSamples'):
  actual=''.join(f'<article class="finished-sample"><a href="{e(x["image"])}"><img src="{e(x["image"])}" width="{int(x["width"])}" height="{int(x["height"])}" alt="{e(x["alt"])}" loading="lazy"></a><h3>{e(x["title"])}</h3><p>{e(x["description"])}</p></article>' for x in c['productSamples'])
  samples='<section class="section-space wrap" id="look-inside"><div class="section-heading">'+head(c['samples']['eyebrow'],c['samples']['heading'],c['samples']['intro'])+'</div><div class="example-grid" id="sample-pages">'+actual+'</div></section>'+samples.replace('id="look-inside"','id="website-examples"').replace('id="sample-pages"','id="website-example-pages"')

 steps=''.join(f'<li><span>{i+1:02d}</span><div><h3>{e(x["title"])}</h3><p>{e(x["body"])}</p></div></li>' for i,x in enumerate(s['startSteps']))
 people=''.join(f'<article class="story-card"><h3>{e(x["name"])}, {e(x["age"])}</h3><p class="story-label">{e(x["label"])}</p><dl><div><dt>{e(c["stories"]["incomeLabel"])}</dt><dd>{e(x["income"])}</dd></div><div><dt>{e(c["stories"]["debtLabel"])}</dt><dd>{e(x["debt"])}</dd></div></dl><p>{e(x["body"])}</p></article>' for x in c['stories']['people'])
 how=f'''<section class="how-section section-space" id="how-it-works"><div class="wrap how-grid"><div>{head(s['howEyebrow'],s['startHeading'],s['startIntro'])}<ol class="start-steps">{steps}</ol></div><div class="people-intro"><p class="eyebrow">{e(c['stories']['eyebrow'])}</p><h3>{e(c['conversationJourney']['storiesHeading'])}</h3><div class="story-grid">{people}</div><p class="composite-note">{e(c['stories']['after'])}</p></div></div></section>'''

 note=f'''<section class="alicia-note"><div class="wrap note-grid"><div class="note-art">{render_tea()}</div><div><p class="eyebrow">{e(c['note']['eyebrow'])}</p><blockquote>{e(c['note']['body'])}</blockquote><p class="signature">{e(c['note']['signature'])}</p></div></div></section>'''
 pricing=f'''<section class="section-space wrap" id="pricing"><div class="section-heading">{head(c['pricing']['eyebrow'],c['pricing']['heading'])}</div><div class="offer-card"><div class="offer-main"><p class="eyebrow">{e(u['packLabel'])}</p><h3>{e(c['pricing']['name'])}</h3><div class="offer-price">{price}<span> USD</span></div><p>{e(c['pricing']['once'])}</p>{buy('pricing',u['access'])}<p class="offer-guarantee">{icon('heart')}{e(u['refundBadge'])}</p><p class="education">{e(u['disclaimer'])}</p></div><div class="offer-includes"><h4>{e(c['pricing']['includedLabel'])}</h4><ul>{''.join(f'<li>{icon("tick")}{e(x["short"])}</li>' for x in c['pack']['items'])}</ul></div></div><div class="refund-line"><strong>{e(c['pricing']['refundHeading'])}</strong><p>{e(c['pricing']['refundBody'])}</p></div>{f'<aside class="setup-notice" id="checkout-setup"><strong>{e(u["checkoutMissing"])}</strong><p>{e(s["offerPreview"])}</p></aside>' if not c['checkoutUrl'] else ''}</section>'''
 faq=f'''<section class="wrap faq section-space"><div>{head(c['faq']['eyebrow'],c['faq']['heading'])}</div><div class="faq-list">{''.join(f'<details data-faq="{i+1}"><summary>{e(x["q"])}{icon("plus")}</summary><p>{e(x["a"])}</p></details>' for i,x in enumerate(c['faq']['items']))}</div></section>'''
 final=f'''<section class="final-cta"><div class="wrap"><p class="eyebrow">{e(c['final']['eyebrow'])}</p><h2>{e(c['final']['heading'])}</h2><p>{e(s['finalBody'])}</p>{buy('final')}<p class="micro">{e(s['offerNote'])}</p></div></section>'''
 free=f'''<section class="free-section wrap"><div><h2>{e(s['freeHeading'])}</h2><p>{e(s['freeBody'])}</p></div><a class="text-link" href="starter-worksheet.html">{e(s['freeLink'])}{icon('arrow')}</a></section>'''
 if c['emailFormAction']:
  free=f'''<section class="free-section wrap"><div><h2>{e(c['free']['heading'])}</h2><p>{e(c['free']['body'])}</p></div><form class="email-form" method="post" action="{e(c['emailFormAction'])}" data-configured="true"><label for="email">{e(u['emailLabel'])}</label><input id="email" type="email" name="{e(c['emailFieldName'])}" autocomplete="email" required><button class="button">{e(u['emailButton'])}</button><p id="newsletter-status">{e(u['emailPrivacy'])}</p></form></section>'''
 import json
 data='<script id="site-config" type="application/json">'+json.dumps({'checkoutUrl':c['checkoutUrl'],'emailSubmitting':u['emailSubmitting'],'motion':c['motion'],'sales':s,'readerDescriptions':c['readers']['descriptions']}).replace('<','\\u003c')+'</script>'
 notice=f'<p class="preview-banner">{e(u["previewNotice"])}</p>' if not c['checkoutUrl'] else ''
 return document(c['seo']['title'],nav+'<main id="main">'+hero+trust+render_conversation(c,icon)+pack+demo+samples+how+render_journey(c,icon)+render_reader_explorer(c,icon)+note+pricing+faq+final+free+'</main>'+foot(True)+notice+data)


def make_printables(c,d):
 s=c['sales']
 for x in s['examples']:
  body=f'''<header class="print-nav"><a href="index.html#sample-pages">{e(s['printBack'])}</a><button onclick="window.print()">{e(s['printButton'])}</button></header><main class="print-sheet"><p class="eyebrow">{e(s['printBrand'])}</p><h1>{e(x['title'])}</h1><p>{e(x['intro'])}</p>{f'<blockquote>{e(x["quote"])}</blockquote>' if x.get('quote') else ''}<ol>{''.join(f'<li>{e(t)}</li>' for t in x['steps'])}</ol>'''
  if x['slug']=='starter-worksheet':
   body+='<table><thead><tr>'+''.join(f'<th>{e(label)}</th>' for label in s['worksheetColumns'])+'</tr></thead><tbody>'+''.join('<tr>'+('<td>&nbsp;</td>'*5)+'</tr>' for _ in range(6))+'</tbody></table>'
  body+=f'<p>{e(x["footer"])}</p><div class="writing-lines" aria-hidden="true"></div><footer>{e(s["printNotice"])}</footer></main>'
  (d/f'{x["slug"]}.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(x["title"])} | Alicia Invests</title><link rel="stylesheet" href="styles.css"><meta name="robots" content="noindex"></head><body class="print-page">{body}</body></html>',encoding='utf-8')
